func splitAmount(total, parts int64) (int64, int64, error) {
    if total <= 0 || parts <= 0 {
        return 0, 0, fmt.Errorf("%w: total=%d parts=%d",
            ErrInvalidSplit, total, parts)
    }
    quotient, remainder := total/parts, total%parts
    return quotient, remainder, nil
}

