func TestSplitAmount(t *testing.T) {
    tests := []struct {
        name         string
        total, parts int64
        wantQ, wantR int64
        wantErr      bool
    }{
        {"exact", 12, 3, 4, 0, false},
        {"remainder", 10, 3, 3, 1, false},
        {"zero total", 0, 3, 0, 0, true},
        {"zero parts", 10, 0, 0, 0, true},
        {"negative parts", 10, -2, 0, 0, true},
        {"negative total", -1, 3, 0, 0, true},
    }
    for _, tt := range tests {
        t.Run(tt.name, func(t *testing.T) {
            q, r, err := splitAmount(tt.total, tt.parts)
            if tt.wantErr {
                if !errors.Is(err, ErrInvalidSplit) {
                    t.Fatalf("err=%v, want ErrInvalidSplit", err)
                }
                return
            }
            if err != nil || q != tt.wantQ || r != tt.wantR {
                t.Fatalf("q=%d r=%d err=%v", q, r, err)
            }
            if q*tt.parts+r != tt.total {
                t.Fatal("amount was not conserved")
            }
        })
    }
}

